} else {
  $(cible).hide(&#39;slide&#39;);
  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqalt1.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&#39;;&quot; /&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;&lt;i&gt;Le personnage peut canaliser l’&#233;nergie divine plus souvent.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Conditions.&lt;/b&gt; Capacit&#233; de &lt;a class=&quot;pagelink&quot; href=&quot;Classes.html&quot; title=&quot;classe&quot;&gt;classe&lt;/a&gt; &#224; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre#Canalisationdenergie.html&quot; title=&quot;canalisation&quot;&gt;canaliser de l’&#233;nergie&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Avantage.&lt;/b&gt; Le personnage &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre#Canalisationdenergie.html&quot; title=&quot;canalisation&quot;&gt;canalise l’&#233;nergie&lt;/a&gt; deux fois de plus par jour.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Sp&#233;cial.&lt;/b&gt; Si un &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html&quot; title=&quot;Le paladin&quot;&gt;paladin&lt;/a&gt; capable de &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre#Canalisationdenergie.html&quot; title=&quot;canalisation&quot;&gt;canaliser de l’&#233;nergie&lt;/a&gt; choisit ce don, il peut utiliser l’&lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#IMPOSITIONDESMAINS&quot; title=&quot;Le paladin&quot;&gt;imposition des mains&lt;/a&gt; quatre fois de plus par jour mais seulement pour &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre#Canalisationdenergie.html&quot; title=&quot;canalisation&quot;&gt;canaliser de l’&#233;nergie positive&lt;/a&gt;. Si un &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre-Combattant.html&quot; title=&quot;Le pr&#234;tre combattant&quot;&gt;pr&#234;tre combattant&lt;/a&gt; poss&#233;dant le pouvoir canalisation d’&#233;nergie prend ce don, il peut utiliser ferveur quatre fois de plus par jour, mais uniquement pour canaliser l’&#233;nergie.
